import { z } from "zod";

export const MAX_VOTERS_PER_TRIP = 30;

export const voteBodySchema = z.object({
  activityId: z.string().min(1).max(60),
  // 1 = thumbs up, -1 = thumbs down, 0 = take my vote back.
  value: z.union([z.literal(1), z.literal(-1), z.literal(0)]),
  // Random id generated by the voter's browser; never shown to anyone.
  voterKey: z.string().regex(/^[A-Za-z0-9_-]{16,64}$/),
  voterName: z
    .string()
    .trim()
    .min(1)
    .max(40)
    // Names are displayed to the trip owner — no control characters or markup brackets.
    .regex(/^[^\u0000-\u001f<>]+$/),
});

export type Tally = { up: number; down: number };

export function tallyVotes(votes: { activityId: string; value: number }[]): Record<string, Tally> {
  const result: Record<string, Tally> = {};
  for (const vote of votes) {
    const entry = (result[vote.activityId] ??= { up: 0, down: 0 });
    if (vote.value > 0) entry.up++;
    else if (vote.value < 0) entry.down++;
  }
  return result;
}

export type Verdict = "favourite" | "voted-down" | "mixed" | "no-votes";

export function verdictFor(tally: Tally | undefined): Verdict {
  if (!tally || tally.up + tally.down === 0) return "no-votes";
  if (tally.down > tally.up) return "voted-down";
  if (tally.up > tally.down) return "favourite";
  return "mixed";
}

// Activities the group clearly doesn't want: strictly more thumbs down than up.
export function votedDownIds(activities: { id: string }[], tallies: Record<string, Tally>): string[] {
  return activities.filter((a) => verdictFor(tallies[a.id]) === "voted-down").map((a) => a.id);
}
